fn test_table_pipe_chars_in_content() {
    // Table cells containing pipe characters are escaped in output
    let html = r#"<table><thead><tr><th>Expression</th><th>Result</th></tr></thead><tbody><tr><td>a | b</td><td>true</td></tr></tbody></table>"#;
    let options: ConversionOptions = Default::default();
    let result = convert(html, Some(options.clone())).expect("call failed");
    let _content = result.content.as_ref().map(|v| v.to_string()).unwrap_or_default();
    assert!(!_content.is_empty(), "expected non-empty value");
    assert!(
        _content.contains(r#"Expression"#),
        "expected to contain: {}",
        r#"Expression"#
    );
    assert!(_content.contains(r#"Result"#), "expected to contain: {}", r#"Result"#);
    assert!(_content.contains(r#"true"#), "expected to contain: {}", r#"true"#);
}

#[test]
fn test_table_ragged_row_fewer_cells_than_header() {
    // A data row with fewer cells than the header is padded to the declared column count
    let html = r#"<table><tr><th>A</th><th>B</th><th>C</th></tr><tr><td>1</td><td>2</td></tr></table>"#;
    let options: ConversionOptions = Default::default();
    let result = convert(html, Some(options.clone())).expect("call failed");
    let _content = result.content.as_ref().map(|v| v.to_string()).unwrap_or_default();
    assert_eq!(
        _content.to_string(),
        r#"| A | B | C |
| --- | --- | --- |
| 1 | 2 |   |
"#,
        "equals assertion failed"
    );
}

#[test]
fn test_table_ragged_row_more_cells_than_header() {
    // A data row with more cells than the header widens the separator so no cell is silently dropped
    let html = r#"<table><tr><th>A</th><th>B</th></tr><tr><td>1</td><td>2</td><td>3</td></tr></table>"#;
    let options: ConversionOptions = Default::default();
    let result = convert(html, Some(options.clone())).expect("call failed");
    let _content = result.content.as_ref().map(|v| v.to_string()).unwrap_or_default();
    assert_eq!(
        _content.to_string(),
        r#"| A | B |   |
| --- | --- | --- |
| 1 | 2 | 3 |
"#,
        "equals assertion failed"
    );
}

#[test]
fn test_table_ragged_rows_padded_not_listed() {
    // A headerless table whose rows have different cell counts is padded, not turned into a list
    let html = r#"<table><tr><td>A</td><td>B</td></tr><tr><td>C</td></tr></table>"#;
    let options: ConversionOptions = Default::default();
    let result = convert(html, Some(options.clone())).expect("call failed");
    let _content = result.content.as_ref().map(|v| v.to_string()).unwrap_or_default();
    assert_eq!(
        _content.to_string(),
        r#"| A | B |
| --- | --- |
| C |   |
"#,
        "equals assertion failed"
    );
}

#[test]
fn test_table_with_alignment() {
    // Table with column alignment attributes
    let html = r#"<table><thead><tr><th align="left">Left</th><th align="center">Center</th><th align="right">Right</th></tr></thead><tbody><tr><td>L</td><td>C</td><td>R</td></tr></tbody></table>"#;
    let options: ConversionOptions = Default::default();
    let result = convert(html, Some(options.clone())).expect("call failed");
    let _content = result.content.as_ref().map(|v| v.to_string()).unwrap_or_default();
    assert!(!_content.is_empty(), "expected non-empty value");
    assert!(_content.contains(r#"Left"#), "expected to contain: {}", r#"Left"#);
    assert!(_content.contains(r#"Center"#), "expected to contain: {}", r#"Center"#);
    assert!(_content.contains(r#"Right"#), "expected to contain: {}", r#"Right"#);
    assert!(_content.contains(r#"L"#), "expected to contain: {}", r#"L"#);
    assert!(_content.contains(r#"C"#), "expected to contain: {}", r#"C"#);
    assert!(_content.contains(r#"R"#), "expected to contain: {}", r#"R"#);
    assert!(_content.contains(r#"|"#), "expected to contain: {}", r#"|"#);
}

#[test]
fn test_table_with_colspan() {
    // Table with colspan attribute in a header cell
    let html = r#"<table><thead><tr><th colspan="2">Full Name</th></tr></thead><tbody><tr><td>John</td><td>Doe</td></tr></tbody></table>"#;
    let options: ConversionOptions = Default::default();
    let result = convert(html, Some(options.clone())).expect("call failed");
    let _content = result.content.as_ref().map(|v| v.to_string()).unwrap_or_default();
    assert!(!_content.is_empty(), "expected non-empty value");
    assert!(
        _content.contains(r#"Full Name"#),
        "expected to contain: {}",
        r#"Full Name"#
    );
    assert!(_content.contains(r#"John"#), "expected to contain: {}", r#"John"#);
    assert!(_content.contains(r#"Doe"#), "expected to contain: {}", r#"Doe"#);
}

#[test]
fn test_tagged_space_in_strikethrough_kept() {
    // A whitespace-only strikethrough keeps the word separator
    let html = r#"<p>A<del> </del>B</p>"#;
    let options: ConversionOptions = Default::default();
    let result = convert(html, Some(options.clone())).expect("call failed");
    let _content = result.content.as_ref().map(|v| v.to_string()).unwrap_or_default();
    assert_eq!(
        _content.to_string(),
        r#"A B
"#,
        "equals assertion failed"
    );
}

